import 'package:flutter/material.dart';
import 'project_record.dart';
import 'project_repository.dart';

const projectStages = ['Solicitado', 'Cotizado', 'Aprobado', 'En desarrollo', 'Revisión', 'Entregado', 'Cancelado'];
class ProjectsScreen extends StatefulWidget { const ProjectsScreen({super.key}); @override State<ProjectsScreen> createState() => _ProjectsScreenState(); }
class _ProjectsScreenState extends State<ProjectsScreen> {
  final repo = ProjectRepository(); final search = TextEditingController(); List<ProjectRecord> values = []; bool loading = true;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { final x = await repo.load(); if (mounted) setState(() { values = x; loading = false; }); }
  Future<void> _save(ProjectRecord p) async { setState(() { final i = values.indexWhere((x) => x.id == p.id); if (i < 0) values = [p, ...values]; else values[i] = p; }); await repo.save(values); }
  Future<void> _delete(ProjectRecord p) async { await repo.markDeleted(p.id); setState(() => values.removeWhere((x) => x.id == p.id)); await repo.save(values); }
  @override void dispose() { search.dispose(); super.dispose(); }
  @override Widget build(BuildContext context) {
    final q = search.text.toLowerCase().trim(); final shown = values.where((p) => '${p.title} ${p.clientName} ${p.stage}'.toLowerCase().contains(q)).toList();
    return Scaffold(body: loading ? const Center(child: CircularProgressIndicator()) : Column(children: [Padding(padding: const EdgeInsets.all(16), child: TextField(controller: search, onChanged: (_) => setState(() {}), decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Buscar proyectos'))), Expanded(child: shown.isEmpty ? Center(child: Text(values.isEmpty ? 'Aún no hay proyectos' : 'Sin resultados')) : ListView.builder(padding: const EdgeInsets.fromLTRB(12, 0, 12, 90), itemCount: shown.length, itemBuilder: (_, i) => _card(shown[i])))]), floatingActionButton: FloatingActionButton.extended(onPressed: () => _edit(), icon: const Icon(Icons.add), label: const Text('Nuevo proyecto')));
  }
  Widget _card(ProjectRecord p) => Card(margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 5), child: ListTile(leading: const CircleAvatar(child: Icon(Icons.work_outline)), title: Text(p.title), subtitle: Text('${p.clientName.isEmpty ? 'Sin cliente asociado' : p.clientName} · ${p.stage} · ${p.value.toStringAsFixed(2)} ${p.currency}'), onTap: () => _edit(p), trailing: PopupMenuButton<String>(onSelected: (v) { if (v == 'edit') _edit(p); if (v == 'delete') _delete(p); }, itemBuilder: (_) => const [PopupMenuItem(value: 'edit', child: Text('Editar')), PopupMenuItem(value: 'delete', child: Text('Eliminar'))])));
  Future<void> _edit([ProjectRecord? old]) async {
    final title = TextEditingController(text: old?.title ?? ''), client = TextEditingController(text: old?.clientName ?? ''), amount = TextEditingController(text: old?.value.toString() ?? ''), paid = TextEditingController(text: old?.paid.toString() ?? ''), deadline = TextEditingController(text: old?.deadline ?? ''), notes = TextEditingController(text: old?.notes ?? ''); var stage = old?.stage ?? projectStages.first; var currency = old?.currency ?? 'USD';
    final result = await showDialog<ProjectRecord>(context: context, builder: (ctx) => StatefulBuilder(builder: (ctx, update) => AlertDialog(title: Text(old == null ? 'Nuevo proyecto' : 'Editar proyecto'), content: SizedBox(width: 440, child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [ _field(title, 'Proyecto *'), _field(client, 'Cliente'), DropdownButtonFormField<String>(value: stage, decoration: const InputDecoration(labelText: 'Etapa'), items: projectStages.map((x) => DropdownMenuItem(value: x, child: Text(x))).toList(), onChanged: (v) => update(() => stage = v ?? stage)), Row(children: [Expanded(child: _field(amount, 'Valor', keyboard: TextInputType.number)), const SizedBox(width: 8), Expanded(child: DropdownButtonFormField<String>(value: currency, decoration: const InputDecoration(labelText: 'Moneda'), items: const ['USD', 'CUP', 'EUR'].map((x) => DropdownMenuItem(value: x, child: Text(x))).toList(), onChanged: (v) => update(() => currency = v ?? currency))]), _field(paid, 'Pagado', keyboard: TextInputType.number), _field(deadline, 'Fecha límite (AAAA-MM-DD)'), _field(notes, 'Notas', lines: 3)]))), actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancelar')), FilledButton(onPressed: () { if (title.text.trim().isEmpty) return; Navigator.pop(ctx, ProjectRecord(id: old?.id ?? DateTime.now().microsecondsSinceEpoch.toString(), title: title.text.trim(), clientName: client.text.trim(), stage: stage, value: double.tryParse(amount.text) ?? 0, paid: double.tryParse(paid.text) ?? 0, currency: currency, deadline: deadline.text.trim(), notes: notes.text.trim(), updatedAt: DateTime.now().toIso8601String())); }, child: const Text('Guardar'))])));
    for (final c in [title, client, amount, paid, deadline, notes]) { c.dispose(); } if (result != null) await _save(result);
  }
  Widget _field(TextEditingController c, String label, {TextInputType? keyboard, int lines = 1}) => Padding(padding: const EdgeInsets.only(top: 8), child: TextField(controller: c, keyboardType: keyboard, maxLines: lines, decoration: InputDecoration(labelText: label)));
}
